/** PushableMbHead describes an MB Head eligible to receive pushed costs for the previewed period. */
export interface PushableMbHead {
  /** MB Head UUID. */
  mbhId: string;
  /** Batch cost code. */
  code: string;
  /** Management display name. */
  name: string;
  /** Whether an ACTUAL cost value is available to push. */
  hasActual: boolean;
  /** Whether a SELLING cost value is available to push. */
  hasSelling: boolean;
  /** Whether a FORECAST cost value is available to push. */
  hasForecast: boolean;
  /**
   * Whether this head was already pushed for the period but its pushed cost has since gone
   * stale — the source cst_product_cost row is SUPERSEDED (or unlinked) and a newer
   * non-superseded row exists. Informational only: such a head is still pushable, and
   * re-pushing is exactly the remedy.
   */
  needsRepush: boolean;
}

/** SkippedMbHead describes an MB Head excluded from the push, with the reason why. */
export interface SkippedMbHead {
  /** MB Head UUID. */
  mbhId: string;
  /** Batch cost code. */
  code: string;
  /** Management display name. */
  name: string;
  /** Reason this head was skipped. */
  reason: string;
}

